let DATA=[],TEAMS=[];
const KCOLORS={Game:'#5A54F0',MKT:'#E0518A',App:'#12A594',Platform:'#E08A1E',BO:'#2B356B',Publishing:'#3F9E56','Khác':'#8A93A3'};
const kcolor=k=>KCOLORS[k]||KCOLORS['Khác'];
const norm=s=>(s||'').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');
const esc=s=>(s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const initials=n=>{const p=n.trim().split(/\s+/);return (p.length==1?p[0].slice(0,2):p[0][0]+p[p.length-1][0]).toUpperCase();};
const KHOI_ORDER=['Game','App','Platform','MKT','Publishing','BO','Khác'];

let byEid={},byNode={},chairman,ceo,EXCL,TEAMS_MAP={},BOM_SET=new Set(),BOD_SET=new Set();
function rebuildMaps(){
 byEid={};byNode={};
 DATA.forEach((p,i)=>{if(p.id==null)p.id=i;p.nodeId=p.eid||('x'+p.id);if(p.eid)byEid[p.eid]=p;byNode[p.nodeId]=p;});
 chairman=DATA.find(p=>/chairman/i.test(p.t))||DATA.find(p=>!p.mgr||!byEid[p.mgr])||DATA[0];
 ceo=DATA.find(p=>/\bceo\b/i.test(p.t))||chairman;
 EXCL=new Set([chairman&&chairman.nodeId,ceo&&ceo.nodeId].filter(Boolean));
}
function rebuildTeams(){TEAMS_MAP={};BOM_SET=new Set();BOD_SET=new Set();TEAMS.forEach(t=>{if(t.eid)TEAMS_MAP[(t.k||'')+'|'+(t.tm||'')]=t.eid;const g=(t.grp||'').toUpperCase();if(g==='BOD'){BOD_SET.add(t.eid);BOM_SET.add(t.eid);}else if(g==='BOM'){BOM_SET.add(t.eid);}});}

const VIEWS=[
 {id:'full',label:'Sơ đồ đầy đủ'},
 {id:'Game',label:'Game',khoi:'Game'},{id:'App',label:'App',khoi:'App'},
 {id:'Platform',label:'Platform',khoi:'Platform'},{id:'MKT',label:'MKT',khoi:'MKT'},
 {id:'Publishing',label:'Publishing',khoi:'Publishing'},{id:'BO',label:'Back Office',khoi:'BO'},
];
function viewCount(v){const r=buildTree(v);const s=new Set();(function w(n){if(n.type==='person'&&passesFilter(n.p))s.add(n.p.nodeId);(n.children||[]).forEach(w);})(r);return s.size;}
function isMgmt(p){return ['Director','Manager','Team Lead'].includes(p.lv)||p.f==='BOD'||!p.mgr;}

let curView=VIEWS[0],collapsed=new Set(),scale=1,query='',panMoved=false;

function personNode(p,teamSet,underCM,seen,pfx){
 pfx=pfx||'';
 const node={type:'person',id:pfx+'p:'+p.nodeId,p,layout:'h',underCM:!!underCM,children:[]};
 if(seen.has(p.nodeId))return node; seen.add(p.nodeId);
 const reps=p.eid?filteredData().filter(x=>teamSet.has(x.nodeId)&&x.mgr===p.eid&&x.nodeId!==p.nodeId&&!seen.has(x.nodeId)):[];
 if(reps.length){
   const byF={};reps.forEach(r=>{(byF[r.f]=byF[r.f]||[]).push(r);});
   node.children=Object.keys(byF).sort((a,b)=>byF[b].length-byF[a].length||a.localeCompare(b)).map(f=>{
     const mem=byF[f].slice().sort((x,y)=>hasRep(x,teamSet)-hasRep(y,teamSet));
     return {type:'cm',id:pfx+'cm:'+p.nodeId+'/'+f,label:f,layout:'v',khoi:p.k,parentTm:p.tm,children:mem.map(m=>personNode(m,teamSet,true,seen,pfx))};
   });
 }
 return node;
}
function hasRep(p,teamSet){return (p.eid&&DATA.some(x=>teamSet.has(x.nodeId)&&x.mgr===p.eid&&x.nodeId!==p.nodeId))?1:0;}

function teamNode(K,T,kp){
 const tp=kp.filter(x=>x.tm===T);const ts=new Set(tp.map(x=>x.nodeId));
 const node={type:'team',id:'team:'+K+'/'+T,label:T,khoi:K,layout:'h',children:[]};
 const pfx='t:'+K+'/'+T+'|';
 const seen=new Set();
 let leadP=byNode[TEAMS_MAP[K+'|'+T]||''];
 if(!leadP){const roots=tp.filter(x=>!ts.has(x.mgr));if(roots.length===1)leadP=roots[0];}
 let host;
 if(leadP){const ln=personNode(leadP,ts,false,seen,pfx);ln.isLead=true;node.children=[ln];host=ln;}
 else host=node;
 const extraByF={};
 tp.forEach(x=>{if(!seen.has(x.nodeId)){const nd=personNode(x,ts,true,seen,pfx);(extraByF[nd.p.f]=extraByF[nd.p.f]||[]).push(nd);}});
 Object.keys(extraByF).sort((a,b)=>extraByF[b].length-extraByF[a].length||a.localeCompare(b)).forEach(f=>
   host.children.push({type:'cm',id:pfx+'cmx:'+f,label:f,layout:'v',khoi:K,parentTm:T,children:extraByF[f]}));
 return node;
}
const TEAM_ORDER={Game:['1945','Falcon Squad','Galaxiga','Prototype','X','Level Game Design','QA']};
function khoiNode(K){
 const kp=filteredData().filter(x=>x.k===K&&!EXCL.has(x.nodeId));
 const cnt={};kp.forEach(x=>cnt[x.tm]=(cnt[x.tm]||0)+1);
 const ord=TEAM_ORDER[K];
 const keys=Object.keys(cnt).sort((a,b)=>{
   if(ord){const ia=ord.indexOf(a),ib=ord.indexOf(b);if(ia>=0||ib>=0)return (ia<0?999:ia)-(ib<0?999:ib);}
   return cnt[b]-cnt[a]||a.localeCompare(b);});
 return {type:'khoi',id:'khoi:'+K,label:K,khoi:K,layout:'h',children:keys.map(T=>teamNode(K,T,kp))};
}
function passesFilter(p){
 const s=(p.st||'Current').trim().toLowerCase();if(![...statusFilter].some(f=>f.toLowerCase()===s))return false;
 const lh=(p.lh||'').trim().toLowerCase();if(![...lhFilter].some(f=>f.toLowerCase()===lh))return false;
 return true;
}
function filteredData(){return DATA.filter(passesFilter);}
function khoiList(){const d=filteredData();const s=new Set(d.filter(p=>!EXCL.has(p.nodeId)).map(p=>p.k));return KHOI_ORDER.filter(k=>s.has(k));}

function buildMgmt(set,label){
 const mg=filteredData().filter(p=>set.has(p.eid));const S=new Set(mg.map(p=>p.nodeId));
 function par(p){let cur=p.mgr,seen=new Set([p.nodeId]);while(cur&&!seen.has(cur)){const n=byEid[cur];if(!n)break;if(S.has(n.nodeId)&&n.nodeId!==p.nodeId)return n;seen.add(cur);if(n.mgr===n.eid)break;cur=n.mgr;}return null;}
 const co={},roots=[];mg.forEach(p=>{const pp=par(p);if(pp&&S.has(pp.nodeId))(co[pp.nodeId]=co[pp.nodeId]||[]).push(p);else roots.push(p);});
 const seen=new Set();
 function mk(p){if(seen.has(p.nodeId))return null;seen.add(p.nodeId);return {type:'person',id:'p:'+p.nodeId,p,layout:'h',children:(co[p.nodeId]||[]).map(mk).filter(Boolean)};}
 const nodes=[];roots.forEach(p=>{const m=mk(p);if(m)nodes.push(m);});mg.forEach(p=>{if(!seen.has(p.nodeId)){const m=mk(p);if(m)nodes.push(m);}});
 if(nodes.length===1)return nodes[0];
 return {type:'khoi',id:'khoi:'+label,label:label,khoi:'Khác',layout:'h',children:nodes};
}
function buildBOM(){return buildMgmt(BOM_SET,'BOM');}
function buildBOD(){return buildMgmt(BOD_SET,'BOD');}
function buildTree(view){
 if(view.id==='bod')return buildBOD();
 if(view.id==='bom')return buildBOM();
 if(view.khoi)return khoiNode(view.khoi);
 // full
 const fd=filteredData();
 const fchairman=fd.find(p=>p.nodeId===(chairman&&chairman.nodeId));
 const fceo=fd.find(p=>p.nodeId===(ceo&&ceo.nodeId));
 const khois=khoiList().map(khoiNode);
 if(!fchairman&&!fceo)return {type:'khoi',id:'khoi:__root',label:'Kết quả lọc',khoi:'Khác',layout:'h',children:khois};
 const ceoN=fceo?{type:'person',id:'p:'+ceo.nodeId,p:ceo,layout:'h',children:khois}:{type:'khoi',id:'khoi:__root',label:'Kết quả lọc',khoi:'Khác',layout:'h',children:khois};
 if(!fchairman)return ceoN;
 return {type:'person',id:'p:'+chairman.nodeId,p:chairman,layout:'h',children:[ceoN]};
}
function pcount(node){let c=(node.type==='person'&&passesFilter(node.p))?1:0;(node.children||[]).forEach(k=>c+=pcount(k));node._c=c;return c;}
// Khối-level counts must be deduped: a khối giám đốc who is also a team/nhóm lead
// appears as a card in more than one branch under the same khối, so raw pcount()
// (which sums every branch) double-counts them. Overwrite _c for type==='khoi'
// nodes with the Set-deduped count (same logic as viewCount / truncateAtKhoi).
function fixKhoiCounts(node){
 if(node.type==='khoi')node._c=viewCount({khoi:node.khoi});
 (node.children||[]).forEach(fixKhoiCounts);
}

function setDefaultCollapsed(root,view){
 collapsed=new Set();pcount(root);
 const topIds=new Set([root.id,(root.children||[])[0]&&(root.children||[])[0].id].filter(Boolean));
 (function w(n){
   if(n.type==='khoi'||(n.type==='person'&&!topIds.has(n.id)&&(n.children||[]).length)){
     collapsed.add(n.id);
   }
   (n.children||[]).forEach(w);
 })(root);
}
// Smart 2-step toggle:
// Khối closed → open, but auto-collapse each team's children (show team box + lead card only)
// Team closed → open fully
// Anything else → normal toggle
function smartToggle(nodeId){
 if(!collapsed.has(nodeId)){
   collapsed.add(nodeId);render();return;
 }
 collapsed.delete(nodeId);
 // find node type
 let nodeType='',nodeKhoi='';
 const root=buildTree(curView);pcount(root);
 (function w(n){if(n.id===nodeId){nodeType=n.type;nodeKhoi=n.khoi;}else(n.children||[]).forEach(w);})(root);
 if(nodeType==='khoi'){
   // when opening a Khối: close each team's sub-children so only team box + lead shows
   (function w(n){
     if(n.id===nodeId){
       (n.children||[]).forEach(teamNode=>{
         if(teamNode.type==='team'){
           // keep team open, but close lead's chuyên môn children
           (teamNode.children||[]).forEach(leadNode=>{
             if(leadNode.type==='person'&&(leadNode.children||[]).length)collapsed.add(leadNode.id);
           });
         }
       });
     }else(n.children||[]).forEach(w);
   })(root);
 }
 render();
}
function computeMatch(root){
 if(!query)return null;const q=norm(query),matched=new Set(),parent={},all=[];
 (function w(n,par){all.push(n);parent[n.id]=par;(n.children||[]).forEach(c=>w(c,n.id));})(root,null);
 all.forEach(n=>{if(n.type==='person'){const p=n.p;if([p.n,p.t,p.tm,p.f].some(v=>norm(v).includes(q)))matched.add(n.id);}});
 const vis=new Set();matched.forEach(id=>{let c=id;while(c!=null){vis.add(c);c=parent[c];}});
 return {matched,vis};
}
function hl(t){if(!query)return esc(t);const n=norm(t),q=norm(query),i=n.indexOf(q);if(i<0)return esc(t);return esc(t.slice(0,i))+'<mark>'+esc(t.slice(i,i+q.length))+'</mark>'+esc(t.slice(i+q.length));}

function cardFor(node,ms){
 if(node.type==='person'){
   const p=node.p;const kc=kcolor(p.k||'Khác');const m=ms&&ms.matched.has(node.id);
   const s=(p.st||'').toLowerCase();const dot=s.includes('replace')?'<span class="sdot rep"></span>':(s.includes('new')?'<span class="sdot new"></span>':'');
   return `<div class="card${m?' match':''}" draggable="${window.isAdmin?'true':'false'}" style="--kc:${kc}" data-id="${esc(p.nodeId)}">${dot}<div class="nm">${hl(p.n)}</div><div class="role">${hl(p.t)}</div><div class="tagrow"><span class="tag" style="--kc:${kc}">${esc(p.k)}</span>${p.by?`<span class="yr">${esc(p.by)}</span>`:''}</div></div>`;
 }
 const khoi=node.khoi||'Khác';
 const cls=node.type==='khoi'?'khoi':node.type==='team'?'team':'cm';
 const dd=node.type==='team'?' data-kt="'+esc(node.khoi+'/'+node.label)+'"':
   node.type==='khoi'?' data-khoi="'+esc(node.label)+'"':
   node.type==='cm'?' data-cm="'+esc(node.khoi+'/'+node.parentTm+'/'+node.label)+'"':'';
 return `<div class="gcard ${cls}" style="--kc:${kcolor(khoi)}"${dd}><div class="gt">${esc(node.label)}</div></div>`;
}
function blockHtml(node,ms,top){
 const card=cardFor(node,ms);
 const has=node.children&&node.children.length;
 const cnt=(!top&&has&&node.type!=='person')?`<div class="node-cnt">${node._c}</div>`:'';
 let kids=node.children||[];
 if(ms)kids=kids.filter(c=>ms.vis.has(c.id));
 if(!kids.length)return cnt+card+'<div class="leafgap"></div>';
 const open=!!query||!collapsed.has(node.id);
 const tog=`<button class="toggle ${open?'':'closed'}" data-tg="${esc(node.id)}"><span class="chev">▾</span></button>`;
 if(!open)return cnt+card+tog;
 let ch;
 if(node.layout==='v'){ch=`<div class="vstack">`+kids.map(c=>`<div class="vnode">${blockHtml(c,ms,false)}</div>`).join('')+`</div>`;}
 else{ch=`<ul class="tree srow">`+kids.map(c=>`<li>${blockHtml(c,ms,false)}</li>`).join('')+`</ul>`;}
 return cnt+card+tog+ch;
}
function render(){
 const scaler=document.getElementById('scaler');
 const view=query?VIEWS[0]:curView;
 const root=buildTree(view);pcount(root);fixKhoiCounts(root);
 const ms=computeMatch(root);
 if(query){
   if(!ms||ms.matched.size===0){scaler.innerHTML='<div class="empty"><div class="b">Không tìm thấy</div><div>Thử từ khoá khác.</div></div>';return;}
   scaler.innerHTML=`<div class="rescount">${ms.matched.size} kết quả trên toàn công ty</div><ul class="tree"><li>${blockHtml(root,ms,true)}</li></ul>`;applyScale();return;
 }
 if(root._c===0){scaler.innerHTML='<div class="empty"><div class="b">Không có nhân sự</div></div>';return;}
 scaler.innerHTML=`<ul class="tree"><li>${blockHtml(root,null,true)}</li></ul>`;applyScale();
}
function setScale(v){scale=Math.min(1.5,Math.max(0.2,+(+v).toFixed(2)));applyScale();}
function applyScale(){document.getElementById('scaler').style.zoom=scale;const z=document.getElementById('zl');if(z&&document.activeElement!==z)z.value=Math.round(scale*100)+'%';}
function fitToView(){const sc=document.getElementById('scaler'),vp=document.getElementById('vp');sc.style.zoom=1;const vw=vp.clientWidth-40,cw=sc.scrollWidth||sc.offsetWidth;scale=cw>vw?Math.max(0.2,vw/cw):1;applyScale();}
function renderTabs(){document.getElementById('tabs').innerHTML=VIEWS.map(v=>{const dot=v.khoi?`<span class="dot" style="background:${kcolor(v.khoi)}"></span>`:'';return `<button class="tab ${v.id===curView.id?'active':''}" data-v="${v.id}">${dot}${esc(v.label)} <span class="c">${viewCount(v)}</span></button>`;}).join('');}
const SF_OPTIONS=['Current','New HC','Replacement'];
let statusFilter=new Set(SF_OPTIONS);
function renderStatusFilter(){
 const menu=document.getElementById('sfMenu');
 const allOn=SF_OPTIONS.every(s=>[...statusFilter].some(f=>f.toLowerCase()===s.toLowerCase()));
 menu.innerHTML=`<button class="sf-item" data-sf="__all"><span class="cb ${allOn?'on':''}">✓</span>Tất cả</button>`+
  SF_OPTIONS.map(s=>{const on=[...statusFilter].some(f=>f.toLowerCase()===s.toLowerCase());
   return `<button class="sf-item" data-sf="${esc(s)}"><span class="cb ${on?'on':''}">✓</span>${esc(s)}</button>`;}).join('');
 const active=SF_OPTIONS.filter(s=>[...statusFilter].some(f=>f.toLowerCase()===s.toLowerCase()));
 document.getElementById('sfBtn').textContent=active.length===SF_OPTIONS.length?'Status: Tất cả ▾':active.length===0?'Status: Không chọn ▾':'Status: '+active.join(', ')+' ▾';
}
(function(){const b=document.getElementById('sfBtn'),m=document.getElementById('sfMenu');
 b.addEventListener('click',e=>{e.stopPropagation();m.classList.toggle('show');});
 m.addEventListener('click',e=>{
  const t=e.target.closest('.sf-item');if(!t)return;
  e.stopPropagation();
  const sf=t.dataset.sf;
  if(sf==='__all'){
   const allOn=SF_OPTIONS.every(s=>[...statusFilter].some(f=>f.toLowerCase()===s.toLowerCase()));
   statusFilter=allOn?new Set():new Set(SF_OPTIONS);
  }else{const existing=[...statusFilter].find(f=>f.toLowerCase()===sf.toLowerCase());
   if(existing)statusFilter.delete(existing);else statusFilter.add(sf);}
  renderStatusFilter();renderLhFilter();renderExportMenu();renderTabs();render();
 });
})();
const LH_OPTIONS=[{v:'Fulltime',l:'Fulltime'},{v:'TTS',l:'Intern'},{v:'CTV',l:'CTV'}];
function lhLabel(v){const o=LH_OPTIONS.find(o=>o.v.toLowerCase()===(v||'').trim().toLowerCase());return o?o.l:v;}
let lhFilter=new Set(LH_OPTIONS.map(o=>o.v));
function renderLhFilter(){
 const menu=document.getElementById('lhMenu');if(!menu)return;
 const allOn=LH_OPTIONS.every(o=>[...lhFilter].some(f=>f.toLowerCase()===o.v.toLowerCase()));
 menu.innerHTML=`<button class="sf-item" data-lh="__all"><span class="cb ${allOn?'on':''}">✓</span>Tất cả</button>`+
  LH_OPTIONS.map(o=>{const on=[...lhFilter].some(f=>f.toLowerCase()===o.v.toLowerCase());
   return `<button class="sf-item" data-lh="${esc(o.v)}"><span class="cb ${on?'on':''}">✓</span>${esc(o.l)}</button>`;}).join('');
 const active=LH_OPTIONS.filter(o=>[...lhFilter].some(f=>f.toLowerCase()===o.v.toLowerCase()));
 const btn=document.getElementById('lhBtn');
 if(btn)btn.textContent=active.length===LH_OPTIONS.length?'Loại hình: Tất cả ▾':active.length===0?'Loại hình: Không chọn ▾':'Loại hình: '+active.map(o=>o.l).join(', ')+' ▾';
}
(function(){const b=document.getElementById('lhBtn'),m=document.getElementById('lhMenu');
 if(!b||!m)return;
 b.addEventListener('click',e=>{e.stopPropagation();m.classList.toggle('show');});
 m.addEventListener('click',e=>{
  const t=e.target.closest('.sf-item');if(!t)return;
  e.stopPropagation();
  const lh=t.dataset.lh;
  if(lh==='__all'){
   const allOn=LH_OPTIONS.every(o=>[...lhFilter].some(f=>f.toLowerCase()===o.v.toLowerCase()));
   lhFilter=allOn?new Set():new Set(LH_OPTIONS.map(o=>o.v));
  }else{const existing=[...lhFilter].find(f=>f.toLowerCase()===lh.toLowerCase());
   if(existing)lhFilter.delete(existing);else lhFilter.add(lh);}
  renderLhFilter();renderTabs();render();
 });
})();
function openModal(p){const kc=kcolor(p.k);document.getElementById('modal').innerHTML=
 `<div class="mh"><div class="avatar" style="background:${kc}">${initials(p.n)}</div><div><h3>${esc(p.n)}</h3><div class="role">${esc(p.t)}</div></div></div>`+
 `<dl>`+
 (p.eid?`<dt>Mã NV</dt><dd>${esc(p.eid)}</dd>`:'')+
 (p.ct?`<dt>Công ty</dt><dd>${esc(p.ct)}</dd>`:'')+
 `<dt>Khối</dt><dd>${esc(p.k)}</dd>`+
 `<dt>Team</dt><dd>${esc(p.tm)}</dd>`+
 (p.mgr&&byEid[p.mgr]?`<dt>Quản lý</dt><dd>${esc(byEid[p.mgr].n)} (${esc(byEid[p.mgr].eid||'')})</dd>`:'')+
 `<dt>Chuyên môn</dt><dd>${esc(p.f)}</dd>`+
 (p.lh?`<dt>Loại hình NS</dt><dd>${esc(lhLabel(p.lh))}</dd>`:'')+
 (p.jd?`<dt>Ngày onboard</dt><dd>${esc(p.jd)}</dd>`:'')+
 (p.nc?`<dt>Ngày chính thức</dt><dd>${esc(p.nc)}</dd>`:'')+
 (window.isAdmin&&p.g?`<dt>Bậc</dt><dd>Bậc ${esc(p.g)}</dd>`:'')+
 (window.isAdmin&&p.lv?`<dt>Cấp</dt><dd>${esc(p.lv)}</dd>`:'')+
 (p.loc?`<dt>Location</dt><dd>${esc(p.loc)}</dd>`:'')+
 (p.em?`<dt>Email</dt><dd><a href="mailto:${esc(p.em)}">${esc(p.em)}</a></dd>`:'')+
 (p.ph?`<dt>SĐT</dt><dd><a href="tel:${esc(p.ph)}">${esc(p.ph)}</a></dd>`:'')+
 (window.isAdmin&&p.st?`<dt>Trạng thái</dt><dd>${esc(p.st)}</dd>`:'')+
 `</dl><div class="mbtns">${window.isAdmin?`<button class="mv" id="mMove">⇄ Di chuyển…</button>`:''}<button id="mx">Đóng</button></div>`;
 document.getElementById('ov').classList.add('show');
 const mMove=document.getElementById('mMove');
 if(mMove)mMove.addEventListener('click',()=>{document.getElementById('ov').classList.remove('show');openMoveDialog(p.nodeId);});
}
document.getElementById('ov').addEventListener('click',e=>{if(e.target.id==='ov'||e.target.id==='mx')document.getElementById('ov').classList.remove('show');});
document.addEventListener('click',e=>{
 if(panMoved){panMoved=false;return;}
 const tab=e.target.closest('.tab');
 if(tab){curView=VIEWS.find(v=>v.id===tab.dataset.v);query='';document.getElementById('q').value='';document.getElementById('clr').style.display='none';setDefaultCollapsed(buildTree(curView),curView);renderTabs();scale=1;render();return;}
 const tg=e.target.closest('.toggle');
 if(tg){smartToggle(tg.dataset.tg);return;}
 const card=e.target.closest('.card');
 if(card){const p=byNode[card.dataset.id];if(p){lastClickedPid=card.dataset.id;openModal(p);}}
});
const q=document.getElementById('q'),clr=document.getElementById('clr');
q.addEventListener('input',()=>{query=q.value.trim();clr.style.display=query?'block':'none';render();});
clr.addEventListener('click',()=>{q.value='';query='';clr.style.display='none';render();});
document.getElementById('expand').addEventListener('click',()=>{collapsed=new Set();render();});
document.getElementById('collapse').addEventListener('click',()=>{setDefaultCollapsed(buildTree(curView),curView);render();});
document.getElementById('zi').addEventListener('click',()=>setScale(scale+0.1));
document.getElementById('zo').addEventListener('click',()=>setScale(scale-0.1));
(function(){const z=document.getElementById('zl');
 const apply=()=>{const n=parseFloat(z.value.replace('%',''));if(!isNaN(n))setScale(n/100);z.value=Math.round(scale*100)+'%';z.blur();};
 z.addEventListener('keydown',e=>{if(e.key==='Enter')apply();});
 z.addEventListener('blur',apply);
})();
