document.addEventListener('keydown',e=>{
 const a=document.activeElement;if(a&&(a.id==='q'||a.id==='zl'))return;
 if(e.key==='+'||e.key==='='){e.preventDefault();setScale(scale+0.1);}
 else if(e.key==='-'||e.key==='_'){e.preventDefault();setScale(scale-0.1);}
 else if(e.key==='0'){e.preventDefault();setScale(1);}
});
function measure(t,f){const c=measure._c||(measure._c=document.createElement('canvas').getContext('2d'));c.font=f;return c.measureText(t||'').width;}
function computeSizes(){
 let tw=0;DATA.forEach(p=>{tw=Math.max(tw,measure(p.n,'600 12.5px Sora,sans-serif'),measure(p.t,'12px Inter,sans-serif'));});
 const cardw=Math.ceil(tw+34);
 document.documentElement.style.setProperty('--card-w',cardw+'px');
}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],f='',q=false;
 for(let i=0;i<text.length;i++){const c=text[i];
  if(q){if(c==='"'){if(text[i+1]==='"'){f+='"';i++;}else q=false;}else f+=c;}
  else{if(c==='"')q=true;else if(c===','){row.push(f);f='';}else if(c==='\r'){}else if(c==='\n'){row.push(f);rows.push(row);row=[];f='';}else f+=c;}}
 if(f!==''||row.length){row.push(f);rows.push(row);}return rows;}
function colFinder(h){const H=h.map(s=>(s||'').replace(/\s+/g,' ').trim().toLowerCase());return pred=>H.findIndex(pred);}
function ingestEmployees(text){
 if(!window.isAdmin)return;
 const rows=parseCSV(text);if(rows.length<2){alert('CSV rỗng');return;}
 const f=colFinder(rows[0]);
 const iName=f(x=>x==='họ và tên'),iEid=f(x=>x==='eid'),iMgr=f(x=>x.includes('report to eid')),
  iKhoi=f(x=>x==='khối'),iFunc=f(x=>x.includes('nhóm vị trí')||x.includes('functional')),iVitri=f(x=>x==='vị trí'),
  iTeam=f(x=>x.includes('team')),iLv=f(x=>x==='level'),iBy=f(x=>x.includes('năm sinh')),iJd=f(x=>x.includes('ngày vào làm')),
  iSt=f(x=>x==='status'),iFal=f(x=>x.includes('email falcon')),iOne=f(x=>x.includes('email onesoft')),
  iG=f(x=>x==='grade'||x==='bậc'),iLoc=f(x=>x==='location'),
  iCt=f(x=>x==='công ty'),iLh=f(x=>x.includes('loại hình')),
  iNc=f(x=>x.includes('ngày lên chính thức')),iPh=f(x=>x.includes('số điện thoại'));
 if(iName<0||iEid<0){alert('Thiếu cột Họ và tên / EID');return;}
 const OK={'current':1,'new hc':1,'newhc':1,'new headcount':1,'replacement':1};
 const out=[];let idx=0;
 for(let r=1;r<rows.length;r++){const x=rows[r];const nm=(x[iName]||'').trim();if(!nm)continue;
  const st=(iSt>=0?x[iSt]:'').trim();if(st&&!OK[st.toLowerCase()])continue;
  const em=(((iFal>=0&&x[iFal])||(iOne>=0&&x[iOne])||'')).trim();const u=em.includes('@')?em.split('@')[0].trim():'';
  const eid=(x[iEid]||'').trim();let mgr=(iMgr>=0?x[iMgr]:'').trim();if(mgr===eid)mgr='';
  out.push({id:idx++,eid,mgr,n:nm,u,em,t:(iVitri>=0?x[iVitri]:'').trim(),k:(iKhoi>=0?x[iKhoi]:'').trim()||'Khác',
   tm:(iTeam>=0?x[iTeam]:'').trim()||'Chưa xếp team',f:(iFunc>=0?x[iFunc]:'').trim()||'Khác',
   lv:(iLv>=0?x[iLv]:'').trim(),g:(iG>=0?x[iG]:'').trim(),st,
   by:(iBy>=0?x[iBy]:'').trim(),jd:(iJd>=0?x[iJd]:'').trim(),
   loc:(iLoc>=0?x[iLoc]:'').trim(),ct:(iCt>=0?x[iCt]:'').trim(),
   lh:(iLh>=0?x[iLh]:'').trim(),nc:(iNc>=0?x[iNc]:'').trim(),ph:(iPh>=0?x[iPh]:'').trim()});}
 DATA=out;rebuildMaps();refreshAll();
 document.getElementById('impInfo').textContent='Đã nạp '+DATA.length+' nhân sự';
}
function ingestTeams(text){
 if(!window.isAdmin)return;
 const rows=parseCSV(text);if(rows.length<2){alert('CSV rỗng');return;}
 const f=colFinder(rows[0]);
 const iK=f(x=>x==='khối'),iT=f(x=>x.includes('team')),iLead=f(x=>x==='lead'),iE=f(x=>x==='eid'),iGr=f(x=>x==='group');
 const out=[];
 for(let r=1;r<rows.length;r++){const x=rows[r];const k=(iK>=0?x[iK]:'').trim(),tm=(iT>=0?x[iT]:'').trim();
  if(!k&&!tm)continue;out.push({k,tm,lead:(iLead>=0?x[iLead]:'').trim(),eid:(iE>=0?x[iE]:'').trim(),grp:(iGr>=0?x[iGr]:'').trim()});}
 TEAMS=out;rebuildTeams();refreshAll();
 document.getElementById('impInfo').textContent='Đã nạp '+TEAMS.length+' team (lead theo Teams CSV)';
}
function refreshAll(){curView=VIEWS[0];query='';document.getElementById('q').value='';document.getElementById('clr').style.display='none';collapsed=new Set();renderStatusFilter();renderLhFilter();renderExportMenu();renderTabs();setDefaultCollapsed(buildTree(curView),curView);scale=1;computeSizes();render();}
function wireFile(inp,fn){inp.addEventListener('change',e=>{const file=e.target.files&&e.target.files[0];if(!file)return;const rd=new FileReader();rd.onload=()=>{try{fn(String(rd.result||''));}catch(err){alert('Lỗi CSV: '+err.message);}};rd.readAsText(file,'utf-8');e.target.value='';});}
