// ---- Undo stack ----
const undoStack=[],redoStack=[];
function saveUndo(){undoStack.push(DATA.map(p=>({...p})));redoStack.length=0;if(undoStack.length>30)undoStack.shift();}
function undo(){if(!window.isAdmin)return;if(!undoStack.length){document.getElementById('impInfo').textContent='Không có gì để hoàn tác';return;}redoStack.push(DATA.map(p=>({...p})));DATA.splice(0,DATA.length,...undoStack.pop());rebuildMaps();rebuildTeams();renderTabs();render();document.getElementById('impInfo').textContent='Đã hoàn tác';}
function redo(){if(!window.isAdmin)return;if(!redoStack.length){document.getElementById('impInfo').textContent='Không có gì để làm lại';return;}undoStack.push(DATA.map(p=>({...p})));DATA.splice(0,DATA.length,...redoStack.pop());rebuildMaps();rebuildTeams();renderTabs();render();document.getElementById('impInfo').textContent='Đã làm lại';}
document.addEventListener('keydown',e=>{
 if((e.ctrlKey||e.metaKey)&&!e.shiftKey&&e.key==='z'){e.preventDefault();undo();}
 if((e.ctrlKey||e.metaKey)&&(e.key==='y'||(e.shiftKey&&e.key==='z'))){e.preventDefault();redo();}
});
function isAncestor(a,b){let cur=b,seen=new Set();while(cur){if(cur.eid&&cur.eid===a.eid)return true;if(seen.has(cur.nodeId))break;seen.add(cur.nodeId);cur=byEid[cur.mgr];}return false;}
(function(){const vp=document.getElementById('vp');let dragId=null;
 vp.addEventListener('dragstart',e=>{if(!window.isAdmin){e.preventDefault();return;}if(e.ctrlKey||e.metaKey){e.preventDefault();return;}const c=e.target.closest('.card[data-id]');if(!c)return;dragId=c.dataset.id;c.classList.add('drag');try{e.dataTransfer.setData('text/plain',dragId);e.dataTransfer.effectAllowed='move';}catch(_){}});
 vp.addEventListener('dragend',e=>{const c=e.target.closest('.card');if(c)c.classList.remove('drag');document.querySelectorAll('.dropok').forEach(n=>n.classList.remove('dropok'));});
 vp.addEventListener('dragover',e=>{const t=e.target.closest('.card[data-id],.gcard.team,.gcard.khoi,.gcard.cm');if(t&&t.dataset.id!==dragId){e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.dropok').forEach(n=>{if(n!==t)n.classList.remove('dropok');});t.classList.add('dropok');}});
 vp.addEventListener('drop',e=>{
  const t=e.target.closest('.card[data-id],.gcard.team,.gcard.khoi,.gcard.cm');
  if(!t||!dragId)return;e.preventDefault();
  document.querySelectorAll('.dropok').forEach(n=>n.classList.remove('dropok'));
  const src=byNode[dragId];dragId=null;if(!src)return;
  saveUndo();
  if(t.dataset.cm){
   const parts=t.dataset.cm.split('/');const K=parts[0],Tm=parts[1],F=parts.slice(2).join('/');
   src.k=K;src.tm=Tm;src.f=F;
   const le=TEAMS_MAP[K+'|'+Tm]||'';if(le&&le!==src.eid)src.mgr=le;
  }else if(t.classList.contains('gcard')){
   if(t.dataset.kt){const[K,Tm]=t.dataset.kt.split('/');src.k=K;src.tm=Tm;const le=TEAMS_MAP[K+'|'+Tm]||'';if(le&&le!==src.eid)src.mgr=le;}
   else if(t.dataset.khoi){src.k=t.dataset.khoi;}
  }else{
   // drop on person → become peer: same team, same cm group as target, mgr = team lead
   const dst=byNode[t.dataset.id];if(!dst||dst.nodeId===src.nodeId)return;
   if(isAncestor(src,dst)){alert('Không thể chuyển: tạo vòng lặp báo cáo');undoStack.pop();return;}
   src.k=dst.k;src.tm=dst.tm;src.f=dst.f;
   // Always set mgr to team lead — never to the person being dropped on
   const teamLead=TEAMS_MAP[dst.k+'|'+dst.tm]||'';
   src.mgr=teamLead&&teamLead!==src.eid?teamLead:(dst.mgr||'');
   if(src.mgr===src.eid)src.mgr='';
  }
  rebuildMaps();rebuildTeams();renderTabs();render();
  document.getElementById('impInfo').textContent='Đã chuyển '+src.n+' → '+src.k+' / '+src.tm+(src.f?' / '+src.f:'');
 });
})();
