function csvEsc(v){v=(v==null?'':String(v));return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v;}
const EXP_COLS=[['EID','eid'],['Họ và tên','n'],['Khối','k'],['Team','tm'],['Nhóm chức năng','f'],['Vị trí','t'],['Cấp','lv'],['Bậc','g'],['Email','em'],['Report to EID','mgr'],['Năm sinh','by'],['Ngày vào làm','jd'],['Trạng thái','st']];
function dlFile(content,type,name){const b=new Blob([content],{type});const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1200);}
function exportCSV(){
 if(!window.isAdmin)return;let s='\uFEFF'+EXP_COLS.map(c=>csvEsc(c[0])).join(',')+'\r\n';DATA.forEach(p=>{s+=EXP_COLS.map(c=>csvEsc(p[c[1]])).join(',')+'\r\n';});dlFile(s,'text/csv;charset=utf-8','falcon-org.csv');}
function exportXLS(){
 if(!window.isAdmin)return;let t='<table border="1"><tr>'+EXP_COLS.map(c=>'<th>'+esc(c[0])+'</th>').join('')+'</tr>';DATA.forEach(p=>{t+='<tr>'+EXP_COLS.map(c=>'<td>'+esc(p[c[1]]==null?'':String(p[c[1]]))+'</td>').join('')+'</tr>';});t+='</table>';dlFile('\uFEFF<html xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="utf-8"></head><body>'+t+'</body></html>','application/vnd.ms-excel','falcon-org.xls');}
