// ---- Font tiếng Việt cho PDF (DejaVu Sans, đã subset) ----
const VN_FONT_REGULAR='';
const VN_FONT_BOLD='';

function newVNDoc(opts){
 const {jsPDF}=window.jspdf||{jsPDF:window.jsPDF};
 const doc=new jsPDF(opts);
 doc.addFileToVFS('DejaVuSans.ttf',VN_FONT_REGULAR);
 doc.addFont('DejaVuSans.ttf','DejaVu','normal');
 doc.addFileToVFS('DejaVuSans-Bold.ttf',VN_FONT_BOLD);
 doc.addFont('DejaVuSans-Bold.ttf','DejaVu','bold');
 doc.setFont('DejaVu','normal');
 return doc;
}
function hexRGB(hex){hex=hex||'#8A93A3';return [parseInt(hex.slice(1,3),16),parseInt(hex.slice(3,5),16),parseInt(hex.slice(5,7),16)];}
function fitText(doc,text,maxW,size,style){
 text=(text||'');doc.setFont('DejaVu',style||'normal');doc.setFontSize(size);
 if(doc.getTextWidth(text)<=maxW)return text;
 let lo=0,hi=text.length;
 while(lo<hi){const mid=Math.ceil((lo+hi)/2);const cand=text.slice(0,mid)+'…';if(doc.getTextWidth(cand)<=maxW)lo=mid;else hi=mid-1;}
 return lo>0?text.slice(0,lo)+'…':'…';
}
// ---- Export PDF: Danh sách (bảng, theo Khối/Team) ----
function exportListPDF(){buildListPDF();}
function buildListPDF(){
 if(!window.isAdmin)return;
 const doc=newVNDoc({orientation:'landscape',unit:'mm',format:'a4'});
 const W=doc.internal.pageSize.getWidth(),H=doc.internal.pageSize.getHeight();
 const kc={Game:'#5A54F0',MKT:'#E0518A',App:'#12A594',Platform:'#E08A1E',BO:'#2B356B',Publishing:'#3F9E56','Khác':'#8A93A3'};
 // page 1: overview – Chairman, CEO, then Khối with counts
 doc.setFillColor(20,25,37);doc.rect(0,0,W,H,'F');
 doc.setTextColor(255,255,255);doc.setFontSize(20);doc.setFont('DejaVu','bold');
 doc.text('SƠ ĐỒ TỔ CHỨC FALCON',W/2,22,{align:'center'});
 doc.setFontSize(10);doc.setFont('DejaVu','normal');doc.setTextColor(150,161,176);
 doc.text(new Date().toLocaleDateString('vi-VN'),W/2,30,{align:'center'});
 if(chairman){doc.setTextColor(255,255,255);doc.setFontSize(11);doc.setFont('DejaVu','bold');doc.text(chairman.n,W/2,48,{align:'center'});doc.setFontSize(9);doc.setFont('DejaVu','normal');doc.setTextColor(150,161,176);doc.text(chairman.t,W/2,54,{align:'center'});}
 if(ceo&&ceo!==chairman){doc.setTextColor(255,255,255);doc.setFontSize(11);doc.setFont('DejaVu','bold');doc.text(ceo.n,W/2,68,{align:'center'});doc.setFontSize(9);doc.setFont('DejaVu','normal');doc.setTextColor(150,161,176);doc.text(ceo.t,W/2,74,{align:'center'});}
 const khois=khoiList();const bw=Math.min(40,(W-20)/khois.length-4);let bx=(W-((bw+4)*khois.length-4))/2;const by=88;
 khois.forEach(k=>{const [r,g,b]=hexRGB(kc[k]);
  doc.setFillColor(r,g,b);doc.roundedRect(bx,by,bw,14,3,3,'F');doc.setTextColor(255,255,255);doc.setFont('DejaVu','bold');doc.setFontSize(9);doc.text(k,bx+bw/2,by+6,{align:'center'});doc.setFont('DejaVu','normal');doc.setFontSize(7);doc.text(DATA.filter(p=>p.k===k).length+' người',bx+bw/2,by+11,{align:'center'});bx+=bw+4;});
 // pages per Khối / Team: bảng danh sách
 khois.forEach(k=>{
  const kppl=DATA.filter(p=>p.k===k);
  const teams=[...new Set(kppl.map(p=>p.tm))];
  const ord=TEAM_ORDER[k];if(ord)teams.sort((a,b)=>{const ia=ord.indexOf(a),ib=ord.indexOf(b);return (ia<0?999:ia)-(ib<0?999:ib);});
  teams.forEach(tm=>{
   const mppl=kppl.filter(p=>p.tm===tm);if(!mppl.length)return;
   doc.addPage();const [r,g,b]=hexRGB(kc[k]);
   doc.setFillColor(r,g,b);doc.rect(0,0,W,16,'F');
   doc.setTextColor(255,255,255);doc.setFont('DejaVu','bold');doc.setFontSize(13);doc.text(k+' · '+tm,10,11);
   doc.setFont('DejaVu','normal');doc.setFontSize(9);doc.text(mppl.length+' nhân sự',W-10,11,{align:'right'});
   const head=[['Họ và tên','Vị trí','Chuyên môn','Bậc','Email','Ngày vào làm','Trạng thái']];
   const body=mppl.map(p=>[p.n||'',p.t||'',p.f||'',p.g?'Bậc '+p.g:'',p.em||'',p.jd||'',p.st||'Current']);
   doc.autoTable({head,body,startY:20,theme:'striped',styles:{font:'DejaVu',fontSize:8.5,cellPadding:2.5},headStyles:{font:'DejaVu',fontStyle:'bold',fillColor:[r,g,b],textColor:255},bodyStyles:{font:'DejaVu'},alternateRowStyles:{fillColor:[240,242,248]},margin:{left:8,right:8},tableWidth:'auto'});
  });
 });
 doc.save('falcon-org-danhsach-'+new Date().toISOString().slice(0,10)+'.pdf');
}
