function exportTreePDF(){buildTreePDF();}
function truncateAtKhoi(node){
 const clone={type:node.type,id:node.id,label:node.label,khoi:node.khoi,p:node.p,_c:node._c};
 if(node.type==='khoi'){clone.children=[];clone._c=viewCount({khoi:node.khoi});return clone;}
 clone.children=(node.children||[]).map(truncateAtKhoi);
 return clone;
}
function treeDescribe(kc){
 return function describe(n){
  if(n.type==='person'){
   return {kind:'person',w:32,h:13,gapX:4,gapY:9,khoi:n.p.k};
  }
  if(n.type==='cm'){
   return {kind:'cm',w:26,h:7,gapX:4,gapY:8,khoi:n.khoi,childW:32,childH:13};
  }
  if(n.type==='khoi'){
   return {kind:'khoi',w:38,h:16,gapX:6,gapY:10,khoi:n.khoi};
  }
  return {kind:'virtual',w:0,h:0,gapX:6,gapY:0,khoi:n.khoi};
 };
}
function layoutTreeNode(n,describe){
 const d=describe(n);n._d=d;
 const kids=n.children||[];
 const mode=(n.layout==='v')?'v':'h';
 n._mode=mode;
 if(!kids.length){n._w=d.w;n._h=d.h;n._kids=[];return n;}
 kids.forEach(k=>layoutTreeNode(k,describe));
 if(mode==='v'){
  const gap=d.gapY||8;let totalH=0;
  kids.forEach((k,i)=>{totalH+=k._h;if(i<kids.length-1)totalH+=gap;});
  n._w=Math.max(d.w,Math.max.apply(null,kids.map(k=>k._w)));
  n._h=d.h+(d.gapY||8)+totalH;
  n._kids=kids;n._childrenH=totalH;
 }else{
  const gap=d.gapX||6;let totalW=0;
  kids.forEach((k,i)=>{totalW+=k._w;if(i<kids.length-1)totalW+=gap;});
  n._w=Math.max(d.w,totalW);
  n._h=d.h+(d.gapY||10)+Math.max.apply(null,kids.map(k=>k._h));
  n._kids=kids;n._childrenW=totalW;
 }
 return n;
}
function assignTreePos(n,x,y){
 const d=n._d;
 n._boxW=d.w;n._boxH=d.h;
 n._x=x+(n._w-d.w)/2;n._y=y;
 if(!n._kids||!n._kids.length)return;
 if(n._mode==='v'){
  let cy=y+d.h+(d.gapY||8);
  n._kids.forEach(k=>{assignTreePos(k,x+(n._w-k._w)/2,cy);cy+=k._h+(d.gapY||8);});
 }else{
  let cx=x+(n._w-n._childrenW)/2;
  const childY=y+d.h+(d.gapY||10);
  n._kids.forEach(k=>{assignTreePos(k,cx,childY);cx+=k._w+(d.gapX||6);});
 }
}
function treeBounds(n,acc){
 acc.maxX=Math.max(acc.maxX,n._x+n._boxW);acc.maxY=Math.max(acc.maxY,n._y+n._boxH);
 (n._kids||[]).forEach(k=>treeBounds(k,acc));
 return acc;
}
function drawTreeBox(doc,d,x,y,w,h,scale,kc){
 if(d.kind==='virtual')return;
 const color=kc(d.khoi);const [r,g,b]=hexRGB(color);
 const rad=Math.min(2.4,h/5);
 if(d.kind==='khoi'){
  doc.setFillColor(r,g,b);doc.roundedRect(x,y,w,h,rad,rad,'F');
 }else if(d.kind==='cm'){
  doc.setFillColor(r,g,b);doc.roundedRect(x,y,w,h,h/2,h/2,'F');
 }else{
  doc.setFillColor(255,255,255);doc.setDrawColor(r,g,b);doc.setLineWidth(Math.max(0.18,0.3*scale));
  doc.roundedRect(x,y,w,h,rad,rad,'FD');
 }
 return {r,g,b};
}
function drawTreeText(doc,n,x,y,w,h,scale,kc){
 const d=n._d;const pad=1.1*scale;
 if(d.kind==='person'){
  const p=n.p;const nameSize=Math.max(4.6,6.6*scale),roleSize=Math.max(3.6,5.2*scale);
  doc.setTextColor(20,25,37);
  const nm=fitText(doc,p.n,w-2*pad,nameSize,'bold');
  doc.text(nm,x+pad,y+h*0.42);
  doc.setTextColor(103,112,127);
  const rl=fitText(doc,p.t||'',w-2*pad,roleSize,'normal');
  doc.text(rl,x+pad,y+h*0.75);
 }else if(d.kind==='cm'){
  const size=Math.max(4,5.6*scale);
  doc.setTextColor(255,255,255);
  const tx=fitText(doc,n.label,w-2*pad,size,'bold');
  doc.setFont('DejaVu','bold');doc.setFontSize(size);
  doc.text(tx,x+w/2,y+h*0.65,{align:'center'});
 }else if(d.kind==='khoi'){
  const titleSize=Math.max(6,8.4*scale),subSize=Math.max(4.4,6*scale);
  doc.setTextColor(255,255,255);
  const tx=fitText(doc,n.label,w-2*pad,titleSize,'bold');
  doc.setFont('DejaVu','bold');doc.setFontSize(titleSize);doc.text(tx,x+w/2,y+h*0.42,{align:'center'});
  doc.setFont('DejaVu','normal');doc.setFontSize(subSize);
  doc.text((n._c||0)+' người',x+w/2,y+h*0.75,{align:'center'});
 }
}
function drawTreeNode(doc,n,scale,offX,offY,kc){
 const d=n._d;
 const bx=offX+n._x*scale,by=offY+n._y*scale,bw=n._boxW*scale,bh=n._boxH*scale;
 if(n._kids&&n._kids.length&&d.kind!=='virtual'){
  const pcx=bx+bw/2,pcy=by+bh;
  doc.setDrawColor(196,202,214);doc.setLineWidth(Math.max(0.15,0.3*scale));
  n._kids.forEach(k=>{
   const ccx=offX+(k._x+k._boxW/2)*scale,ccy=offY+k._y*scale;
   const midY=pcy+(ccy-pcy)/2;
   doc.line(pcx,pcy,pcx,midY);doc.line(pcx,midY,ccx,midY);doc.line(ccx,midY,ccx,ccy);
  });
 }else if(n._kids&&n._kids.length&&d.kind==='virtual'){
  // virtual root: no box/line of its own, children start right at its position
 }
 if(d.kind!=='virtual'){drawTreeBox(doc,d,bx,by,bw,bh,scale,kc);drawTreeText(doc,n,bx,by,bw,bh,scale,kc);}
 (n._kids||[]).forEach(k=>drawTreeNode(doc,k,scale,offX,offY,kc));
}
function buildTreePDF(){
 if(!window.isAdmin)return;
 const doc=newVNDoc({orientation:'landscape',unit:'mm',format:'a4'});
 const W=doc.internal.pageSize.getWidth(),H=doc.internal.pageSize.getHeight();
 const kcMap={Game:'#5A54F0',MKT:'#E0518A',App:'#12A594',Platform:'#E08A1E',BO:'#2B356B',Publishing:'#3F9E56','Khác':'#8A93A3'};
 const kc=k=>kcMap[k]||kcMap['Khác'];
 const describeOverview=treeDescribe(kc);
 // Slide 1: cây rút gọn (Chairman → CEO → Khối, không đi sâu vào người)
 doc.setFillColor(20,25,37);doc.rect(0,0,W,H,'F');
 doc.setTextColor(255,255,255);doc.setFont('DejaVu','bold');doc.setFontSize(18);
 doc.text('SƠ ĐỒ TỔ CHỨC FALCON — Sơ đồ tổng quan',W/2,16,{align:'center'});
 doc.setFont('DejaVu','normal');doc.setFontSize(9);doc.setTextColor(150,161,176);
 doc.text(new Date().toLocaleDateString('vi-VN'),W/2,22,{align:'center'});
 const fullRoot=buildTree(VIEWS[0]);pcount(fullRoot);
 const overviewRoot=truncateAtKhoi(fullRoot);
 overviewRoot._describe=(n)=>{
  const dd=describeOverview(n);
  if(n.type==='khoi'){dd.w=42;dd.h=18;dd.gapX=8;}
  if(n.type==='person'){dd.w=46;dd.h=16;}
  return dd;
 };
 // Vẽ tay slide overview trên nền tối (đổi màu chữ/khung cho hợp nền tối)
 (function drawOverviewDark(){
  layoutTreeNode(overviewRoot,overviewRoot._describe);
  assignTreePos(overviewRoot,0,0);
  const b=treeBounds(overviewRoot,{maxX:0,maxY:0});
  const areaX=10,areaY=30,areaW=W-20,areaH=H-40;
  const scale=Math.min(1,areaW/Math.max(1,b.maxX),areaH/Math.max(1,b.maxY));
  const offX=areaX+(areaW-b.maxX*scale)/2,offY=areaY;
  (function draw(n){
   const d=n._d;
   const bx=offX+n._x*scale,by=offY+n._y*scale,bw=n._boxW*scale,bh=n._boxH*scale;
   if(n._kids&&n._kids.length){
    const pcx=bx+bw/2,pcy=by+bh;
    doc.setDrawColor(90,98,120);doc.setLineWidth(0.35);
    n._kids.forEach(k=>{
     const ccx=offX+(k._x+k._boxW/2)*scale,ccy=offY+k._y*scale;
     const midY=pcy+(ccy-pcy)/2;
     doc.line(pcx,pcy,pcx,midY);doc.line(pcx,midY,ccx,midY);doc.line(ccx,midY,ccx,ccy);
    });
   }
   if(d.kind==='person'){
    const p=n.p;const [r,g,b2]=hexRGB(kc(p.k));
    doc.setFillColor(30,36,52);doc.setDrawColor(r,g,b2);doc.setLineWidth(0.4);
    doc.roundedRect(bx,by,bw,bh,2.4,2.4,'FD');
    const nameSize=Math.max(5,7*scale),roleSize=Math.max(4,5.4*scale);
    doc.setTextColor(255,255,255);doc.setFont('DejaVu','bold');doc.setFontSize(nameSize);
    doc.text(fitText(doc,p.n,bw-4,nameSize,'bold'),bx+bw/2,by+bh*0.42,{align:'center'});
    doc.setTextColor(170,178,196);doc.setFont('DejaVu','normal');doc.setFontSize(roleSize);
    doc.text(fitText(doc,p.t||'',bw-4,roleSize,'normal'),bx+bw/2,by+bh*0.75,{align:'center'});
   }else if(d.kind==='khoi'){
    drawTreeBox(doc,d,bx,by,bw,bh,scale,kc);
    const titleSize=Math.max(6.5,9*scale),subSize=Math.max(4.6,6.2*scale);
    doc.setTextColor(255,255,255);doc.setFont('DejaVu','bold');doc.setFontSize(titleSize);
    doc.text(fitText(doc,n.label,bw-4,titleSize,'bold'),bx+bw/2,by+bh*0.42,{align:'center'});
    doc.setFont('DejaVu','normal');doc.setFontSize(subSize);
    doc.text((n._c||0)+' người',bx+bw/2,by+bh*0.75,{align:'center'});
   }
   (n._kids||[]).forEach(draw);
  })(overviewRoot);
 })();
 // Các slide sau: theo từng Khối / Team — sơ đồ cây thật (khung + đường nối)
 const khois=khoiList();
 khois.forEach(k=>{
  const kppl=DATA.filter(p=>p.k===k&&!EXCL.has(p.nodeId));
  const teamNames=[...new Set(kppl.map(p=>p.tm))];
  const ord=TEAM_ORDER[k];if(ord)teamNames.sort((a,b)=>{const ia=ord.indexOf(a),ib=ord.indexOf(b);return (ia<0?999:ia)-(ib<0?999:ib);});
  teamNames.forEach(tm=>{
   const node=teamNode(k,tm,kppl);
   let root=node.children&&node.children.length===1&&node.children[0].type==='person'?node.children[0]:{type:'virtual',khoi:k,layout:'h',children:node.children||[]};
   root._describe=treeDescribe(kc);
   // Layout trước (chưa cần trang) để biết cây cao/rộng bao nhiêu — rồi mới tạo trang
   // vừa đúng kích thước đó, giống hiển thị dọc trên web thay vì gò ép vào khổ A4 cố định.
   layoutTreeNode(root,root._describe);
   assignTreePos(root,0,0);
   const b=treeBounds(root,{maxX:0,maxY:0});
   const margin=10,headerH=24,bottomMargin=10;
   const maxPageW=420,maxPageH=1600,minPageW=140,minPageH=60;
   const pageW=Math.min(maxPageW,Math.max(minPageW,b.maxX+2*margin));
   const pageH=Math.min(maxPageH,Math.max(minPageH,headerH+b.maxY+bottomMargin));
   doc.addPage([pageW,pageH],pageW>=pageH?'l':'p');
   const pW=doc.internal.pageSize.getWidth(),pH=doc.internal.pageSize.getHeight();
   const [r,g,b2]=hexRGB(kc(k));
   doc.setFillColor(r,g,b2);doc.rect(0,0,pW,16,'F');
   doc.setTextColor(255,255,255);doc.setFont('DejaVu','bold');doc.setFontSize(13);doc.text(k+' · '+tm,10,11);
   const cntSet=new Set();(function cw(nd){if(nd.type==='person')cntSet.add(nd.p.nodeId);(nd.children||[]).forEach(cw);})(root);
   const cnt=cntSet.size;
   doc.setFont('DejaVu','normal');doc.setFontSize(9);doc.text(cnt+' nhân sự',pW-10,11,{align:'right'});
   const areaW=pW-2*margin,areaH=pH-headerH-bottomMargin;
   const scale=Math.min(1,areaW/Math.max(1,b.maxX),areaH/Math.max(1,b.maxY));
   const offX=margin+(areaW-b.maxX*scale)/2,offY=headerH;
   drawTreeNode(doc,root,scale,offX,offY,kc);
  });
 });
 doc.save('falcon-org-sodo-'+new Date().toISOString().slice(0,10)+'.pdf');
}
let lastClickedPid=null;
// ---- Đăng nhập Google & phân quyền Admin/Nhân viên (xác thực thật ở server) ----
// Trình duyệt chỉ nhận ID token đã ký từ Google, gửi lên server để server xác
// minh chữ ký + domain @falcongames.com rồi mới cấp session (cookie httpOnly).
// Dữ liệu nhân sự (DATA/TEAMS) chỉ được server trả về sau khi có session hợp lệ.
window.isAdmin = false;
const gate=document.getElementById('ovGate'),mwrap=document.getElementById('mainWrap'),
 gErr=document.getElementById('gateErr'),gSpin=document.getElementById('gateSpinner');

function applyRole(admin){
 window.isAdmin=!!admin;
 document.body.classList.toggle('is-admin',window.isAdmin);
 const badge=document.getElementById('roleBadge');
 if(badge){badge.textContent=window.isAdmin?'Admin':'Nhân viên';badge.className='role-badge '+(window.isAdmin?'admin':'staff');}
 const sub=document.getElementById('subLine');
 if(sub){const txt=window.isAdmin?'Kéo-thả nhân sự để sắp xếp lại · Ctrl+kéo để di chuyển khung · bấm card xem chi tiết':'Bấm vào card để xem chi tiết nhân sự';
  sub.childNodes[0].nodeValue=txt;}
 const foot=document.getElementById('footLine');
 if(foot)foot.textContent=window.isAdmin?'Bản quản trị (Admin) · thay đổi kéo-thả chỉ áp dụng trong phiên, chưa lưu · dùng Import/Export để nạp và lưu dữ liệu.':'Sơ đồ tổ chức Falcon · chỉ dành cho nhân viên Falcon Games.';
}
function initApp(admin){
 applyRole(admin);
 rebuildMaps();rebuildTeams();renderStatusFilter();renderLhFilter();renderExportMenu();renderTabs();
 setDefaultCollapsed(buildTree(curView),curView);scale=1;computeSizes();render();
 if(document.fonts&&document.fonts.ready)document.fonts.ready.then(computeSizes);
}
function showGateErr(msg){gErr.textContent=msg||'Đăng nhập thất bại. Vui lòng thử lại.';gErr.style.display='block';}
async function loadOrgDataAndStart(admin){
 gSpin.style.display='block';gErr.style.display='none';
 try{
  const res=await fetch('/api/org-data',{credentials:'same-origin'});
  if(!res.ok){
   if(res.status===401){gate.classList.add('show');gSpin.style.display='none';return;}
   throw new Error('load-failed');
  }
  const j=await res.json();
  DATA=j.data||[];TEAMS=j.teams||[];
  gate.classList.remove('show');mwrap.style.display='';
  initApp(admin);
 }catch(e){
  gSpin.style.display='none';
  showGateErr('Không tải được dữ liệu tổ chức. Vui lòng tải lại trang.');
 }
}
async function handleGoogleCredential(response){
 gErr.style.display='none';gSpin.style.display='block';
 try{
  const res=await fetch('/api/auth/google',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({credential:response.credential})});
  const j=await res.json().catch(()=>({}));
  if(!res.ok||!j.ok){gSpin.style.display='none';showGateErr(j.error||'Đăng nhập thất bại.');return;}
  loadOrgDataAndStart(j.role==='admin');
 }catch(e){
  gSpin.style.display='none';
  showGateErr('Lỗi kết nối máy chủ. Vui lòng thử lại.');
 }
}
window.handleGoogleCredential=handleGoogleCredential;
document.getElementById('switchRole').addEventListener('click',async()=>{
 try{await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'});}catch(_){}
 try{if(window.google&&google.accounts&&google.accounts.id)google.accounts.id.disableAutoSelect();}catch(_){}
 location.reload();
});
// Kiểm tra phiên đăng nhập hiện có (nếu đã đăng nhập trước đó, không cần đăng nhập lại)
(async function(){
 try{
  const res=await fetch('/api/session',{credentials:'same-origin'});
  if(res.ok){
   const j=await res.json();
   if(j.authenticated){loadOrgDataAndStart(j.role==='admin');return;}
  }
 }catch(_){}
 gate.classList.add('show');
})();
